begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temporary table fixture as select document from public.curriculum_versions where id='00000000-0000-0000-0000-000000000101';
create temporary table preferences(p jsonb);
insert into preferences values(jsonb_build_object('schemaVersion',1,'timezone','UTC','lessonDurationMinutes',30,'weeklyFrequency',2,'slots','[{"weekday":1,"time":"16:00"},{"weekday":3,"time":"16:00"}]'::jsonb,'earliestDate',to_char(current_date+7,'YYYY-MM-DD')));
create temporary table enrolled(id uuid);
create temporary table draft(id uuid);
grant select on fixture,preferences to authenticated;grant all on enrolled,draft to authenticated;
select ok(not has_function_privilege('anon','public.enroll_parent_student(uuid,uuid,uuid,jsonb)','EXECUTE'),'anonymous enrollment execution denied');
select ok(not has_function_privilege('authenticated','public.build_initial_course_plan(jsonb,integer)','EXECUTE'),'planner is internal');
select is(public.build_initial_course_plan((select document from fixture),30)->>'lessonCount','4','four planned lessons');
select is(public.build_initial_course_plan((select document from fixture),30)->>'totalEstimatedMinutes','120','all instructional minutes preserved');
select is(jsonb_array_length(public.build_initial_course_plan((select document from fixture),30)->'items'),7,'skills split into seven ordered segments');
select is((public.build_initial_course_plan((select document from fixture),30)->'items'->0)->>'skillId','00000000-0000-0000-0000-000000000011','academic prerequisite order');
select throws_ok($$select public.build_initial_course_plan((select document from fixture),10)$$,'22023',null,'duration rejected');
select throws_ok($$select public.validate_initial_preferences((select p from preferences)||'{"weeklyFrequency":3}')$$,'22023',null,'frequency must match explicit availability');
select throws_ok($$select public.validate_initial_preferences((select p from preferences)||'{"timezone":"Unknown/Place"}')$$,'22023',null,'timezone rejected');
select throws_ok($$select public.validate_initial_preferences((select p from preferences)||'{"earliestDate":"2026-02-30"}')$$,'22023',null,'impossible date rejected');
select is(public.resolve_initial_local_time('2026-03-02 16:00','Asia/Kolkata'),'2026-03-02 10:30Z'::timestamptz,'fractional timezone offset');
select is(public.resolve_initial_local_time('2026-03-02 16:00','America/New_York'),'2026-03-02 21:00Z'::timestamptz,'winter UTC offset');
select is(public.resolve_initial_local_time('2026-03-09 16:00','America/New_York'),'2026-03-09 20:00Z'::timestamptz,'summer UTC offset');
select throws_ok($$select public.resolve_initial_local_time('2026-03-08 02:30','America/New_York')$$,'P3001',null,'DST gap rejected');
select throws_ok($$select public.resolve_initial_local_time('2026-11-01 01:30','America/New_York')$$,'P3001',null,'DST fold rejected');
select throws_ok($$select public.resolve_initial_local_time('2026-10-04 02:15','Australia/Lord_Howe')$$,'P3001',null,'half-hour DST gap rejected');
select throws_ok($$select public.resolve_initial_local_time('2026-04-05 01:45','Australia/Lord_Howe')$$,'P3001',null,'half-hour DST fold rejected');
select is((public.build_initial_lesson_schedule((select p from preferences)||'{"timezone":"America/New_York","earliestDate":"2026-03-02"}',4,'2026-03-01T12:00Z')->2->>'startsAt')::timestamptz,'2026-03-09T20:00Z'::timestamptz,'weekly recurrence preserves local wall time across DST');
select throws_ok($$select public.build_initial_lesson_schedule((select p from preferences)||'{"earliestDate":"2026-03-01"}',4,'2026-04-01T12:00Z')$$,'22023',null,'past starting date rejected');
insert into auth.users(id,email_confirmed_at,raw_user_meta_data) values
 ('a3000000-0000-0000-0000-000000000001',now(),'{"role":"ADMIN"}'),
 ('a3000000-0000-0000-0000-000000000002',now(),'{}'),
 ('a3000000-0000-0000-0000-000000000003',now(),'{}'),
 ('a3000000-0000-0000-0000-000000000004',now(),'{}'),
 ('a3000000-0000-0000-0000-000000000005',null,'{}');
insert into public.users(id,role) values
 ('a3000000-0000-0000-0000-000000000001','PARENT'),('a3000000-0000-0000-0000-000000000002','PARENT'),('a3000000-0000-0000-0000-000000000003','STUDENT'),('a3000000-0000-0000-0000-000000000004','ADMIN'),('a3000000-0000-0000-0000-000000000005','PARENT');
insert into public.parent_profiles(user_id,display_name) values('a3000000-0000-0000-0000-000000000001','Synthetic A'),('a3000000-0000-0000-0000-000000000002','Synthetic B'),('a3000000-0000-0000-0000-000000000005','Unverified');
insert into public.student_profiles(id,user_id,display_name) values('a3100000-0000-0000-0000-000000000001','a3000000-0000-0000-0000-000000000003','Synthetic learner A'),('a3100000-0000-0000-0000-000000000002',null,'Synthetic learner B'),('a3100000-0000-0000-0000-000000000003',null,'Atomic rollback learner');
insert into public.parent_student_relationships values('a3000000-0000-0000-0000-000000000001','a3100000-0000-0000-0000-000000000001'),('a3000000-0000-0000-0000-000000000002','a3100000-0000-0000-0000-000000000002'),('a3000000-0000-0000-0000-000000000001','a3100000-0000-0000-0000-000000000003');
-- Reserve the rollback student's exact first preferred slot; enrollment must fail after inserts without retaining any state.
insert into public.lesson_schedules(student_id,starts_at,ends_at) select 'a3100000-0000-0000-0000-000000000003',(entry->>'startsAt')::timestamptz,(entry->>'endsAt')::timestamptz from jsonb_array_elements(public.build_initial_lesson_schedule((select p from preferences),4,clock_timestamp())) with ordinality slots(entry,rank) where rank=1;
set local role authenticated;
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000099','a3100000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000101',(select p from preferences))$$,'42501',null,'parent cannot enroll another family');
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000003','a3100000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000101',(select p from preferences))$$,'23P01',null,'overlapping schedule rejected');
select is((select count(*)::integer from public.student_courses where student_id='a3100000-0000-0000-0000-000000000003'),0,'failed enrollment rolled back');
select is((select count(*)::integer from public.student_skills where student_id='a3100000-0000-0000-0000-000000000003'),0,'failed skill initialization rolled back');
select is((select count(*)::integer from public.availability_preferences where student_id='a3100000-0000-0000-0000-000000000003'),0,'failed availability rolled back');
insert into enrolled select public.enroll_parent_student('a3200000-0000-0000-0000-000000000001','a3100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',(select p from preferences));
select is((select initialization_state from public.student_courses where id=(select id from enrolled)),'ready','complete enrollment ready');
select is((select curriculum_version_id from public.student_courses where id=(select id from enrolled)),'00000000-0000-0000-0000-000000000101'::uuid,'selected version pinned');
select is((select count(*)::integer from public.student_skills where student_id='a3100000-0000-0000-0000-000000000001'),5,'all relevant skills initialized');
select ok(not exists(select 1 from public.student_skills where student_id='a3100000-0000-0000-0000-000000000001' and (assessment_state<>'unassessed' or mastery_score<>0 or confidence<>0 or evidence_count<>0 or last_evidence_id is not null)),'no fabricated mastery or diagnostic evidence');
select is((select count(*)::integer from public.learning_evidence),0,'enrollment adds no learning evidence');
select is((select count(*)::integer from public.course_plans where student_course_id=(select id from enrolled)),1,'one persisted plan');
select is((select count(*)::integer from public.lesson_schedules where course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled))),4,'four canonical scheduled lessons');
select is((select count(*)::integer from public.course_plan_items where course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled))),7,'seven persisted skill segments');
select is((select sum(estimated_minutes)::integer from public.course_plan_items where course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled))),120,'persisted instructional minutes complete');
select ok(not exists(select 1 from public.course_plan_items where course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled)) and projected_date is null),'every segment has a projected local date');
select ok(not exists(select 1 from public.lesson_schedules where course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled)) and (ends_at-starts_at<>interval '30 minutes' or timezone<>'UTC')),'canonical reservation duration and timezone');
select ok(not exists(select 1 from fixture f cross join lateral jsonb_array_elements(f.document->'prerequisites') edge where (select max(position) from public.course_plan_items where skill_id=(edge->>'prerequisiteId')::uuid and course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled))) >= (select min(position) from public.course_plan_items where skill_id=(edge->>'skillId')::uuid and course_plan_id in(select id from public.course_plans where student_course_id=(select id from enrolled)))),'persisted prerequisite work precedes dependent work');
select ok(not exists(select 1 from public.course_plans where student_course_id=(select id from enrolled) and curriculum_version_id<>'00000000-0000-0000-0000-000000000101'),'plan retains version pin');
select is(public.enroll_parent_student('a3200000-0000-0000-0000-000000000001','a3100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',(select p from preferences)),(select id from enrolled),'same request returns same enrollment');
select is(public.enroll_parent_student('a3200000-0000-0000-0000-000000000002','a3100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',(select p from preferences)),(select id from enrolled),'different retry returns existing enrollment');
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000004','a3100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',(select p from preferences)||'{"lessonDurationMinutes":45}')$$,'P3003',null,'retry cannot rewrite preferences');
select throws_ok($$update public.student_skills set mastery_score=1$$,'42501',null,'parent cannot change skill state');
select throws_ok($$update public.lesson_schedules set starts_at=now()$$,'42501',null,'parent cannot arbitrarily reschedule');
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from public.student_courses),0,'other family cannot see enrollment');
select is((select count(*)::integer from public.course_plans),0,'other family cannot see plan');
select is((select count(*)::integer from public.course_plan_items),0,'other family cannot see roadmap items');
select is((select count(*)::integer from public.lesson_schedules),0,'other family cannot see schedule');
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000003',true);
select is((select count(*)::integer from public.student_courses),1,'student sees only own enrollment');
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000005','a3100000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000101',(select p from preferences))$$,'42501',null,'student cannot impersonate a parent');
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000005',true);
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000005','a3100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',(select p from preferences))$$,'42501',null,'unverified parent cannot enroll');
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000004',true);
insert into draft select public.save_curriculum_draft('00000000-0000-0000-0000-000000000002',null,0,(select document from fixture));
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000006','a3100000-0000-0000-0000-000000000001',(select id from draft),(select p from preferences))$$,'22023',null,'unpublished version rejected');
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000004',true);
select public.publish_curriculum_version((select id from draft),1);
select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000001',true);
select is((select curriculum_version_id from public.student_courses where id=(select id from enrolled)),'00000000-0000-0000-0000-000000000101'::uuid,'new publication does not migrate enrollment');
select throws_ok($$select public.enroll_parent_student('a3200000-0000-0000-0000-000000000007','a3100000-0000-0000-0000-000000000001',(select id from draft),(select p from preferences))$$,'P3003',null,'retry with different published version does not migrate');
reset role;
select is((select count(*)::integer from public.audit_logs where action='planning.enrolled'),1,'enrollment audit once');
select is((select count(*)::integer from public.schedule_changes where trigger='initial_enrollment'),1,'initial schedule audit once');
select throws_ok($$insert into public.lesson_schedules(student_id,starts_at,ends_at) select student_id,starts_at,ends_at from public.lesson_schedules where course_plan_id is not null limit 1$$,'23P01',null,'database rejects duplicate reservations');
select lives_ok($$insert into public.lesson_schedules(student_id,starts_at,ends_at) select student_id,ends_at,ends_at+interval '30 minutes' from public.lesson_schedules where course_plan_id is not null order by starts_at desc limit 1$$,'touching intervals are allowed');
select throws_ok($$update public.availability_preferences set student_id='a3100000-0000-0000-0000-000000000002' where student_course_id=(select id from enrolled)$$,'23503',null,'cross-student availability rejected');
select throws_ok($$update public.lesson_schedules set student_id='a3100000-0000-0000-0000-000000000002' where course_plan_id is not null$$,'23503',null,'cross-student reservation rejected');
insert into public.skills(id,topic_id,code,title) values('a3300000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000004','outside-pinned-requirements','Draft-only skill');
select throws_ok($$update public.course_plan_items set skill_id='a3300000-0000-0000-0000-000000000001' where lesson_position is not null$$,'23503',null,'plan skill outside pinned version rejected');
insert into public.student_profiles(id,display_name) values('a3100000-0000-0000-0000-000000000004','Existing evidence learner');
insert into public.parent_student_relationships values('a3000000-0000-0000-0000-000000000001','a3100000-0000-0000-0000-000000000004');
insert into public.learning_evidence(id,student_id,skill_id,evidence_type) values('a3400000-0000-0000-0000-000000000001','a3100000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000011','synthetic_independent_answer');
insert into public.student_skills(student_id,skill_id,mastery_score,confidence,evidence_count,last_evidence_id) values('a3100000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000011',0.5,0.5,1,'a3400000-0000-0000-0000-000000000001');
set local role authenticated;select set_config('request.jwt.claim.sub','a3000000-0000-0000-0000-000000000001',true);
select public.enroll_parent_student('a3200000-0000-0000-0000-000000000008','a3100000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000101',(select p from preferences));
select is((select mastery_score from public.student_skills where student_id='a3100000-0000-0000-0000-000000000004' and skill_id='00000000-0000-0000-0000-000000000011'),0.500::numeric,'genuine existing mastery preserved');
select is((select assessment_state from public.student_skills where student_id='a3100000-0000-0000-0000-000000000004' and skill_id='00000000-0000-0000-0000-000000000011'),'evidenced','existing provenance remains evidenced');
reset role;
select * from finish();rollback;
